// Independent standard Rust for_each over borrowed, read-only source slices.
type String=std::borrow::Cow<'static,str>;
fn string_weight(value:&str,input:&str)->i64{let mut weight=1_i64;for (condition,extra) in [(value==input,3),(value.contains('\0'),5),(value=="e\u{301}",7),(value=="é",11),(value=="😀",13)]{if condition{weight=weight.checked_add(extra).unwrap();}}weight}
struct Row{n:i64,text:String,values:Vec<i64>}
fn row_weight(value:&Row,input:&str)->i64{value.values.iter().fold(value.n.checked_add(string_weight(&value.text,input)).unwrap(),|weight,item|weight.checked_add(*item).unwrap())}
fn function0(value0: i64, value1: i64, value2: &String) -> i64 {let base=[Row{n:value1,text:String::Owned(value2.to_string()),values:vec![value1,1]},Row{n:2,text:String::Borrowed("é"),values:vec![]},Row{n:3,text:String::Borrowed("a\0b"),values:vec![2,3]},Row{n:4,text:String::Borrowed("😀"),values:vec![4]},Row{n:5,text:String::Borrowed("e\u{301}"),values:vec![5,6]}];let mut trace=value1;let mut visits=0_i64;for i in 0..value0{let mode=i.checked_add(value1).unwrap()%5;let count=[0_usize,1,4,5,5][usize::try_from(mode).unwrap()];let selected=&base[..count];selected.iter().enumerate().for_each(|(index,value)|{let weight=row_weight(value,value2);trace=trace.checked_mul(131).unwrap().checked_add(weight).unwrap().checked_add(i64::try_from(index).unwrap()).unwrap().checked_add(i64::try_from(selected.len()).unwrap()).unwrap().checked_add(i).unwrap()%1000000007;visits=visits.checked_add(1).unwrap();});}trace.checked_add(visits).unwrap()%1000000007}
fn main(){}
